import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Command line","description":"","frontmatter":{},"headers":[],"relativePath":"reference/command-line.md","filePath":"reference/command-line.md"}`),a={name:`reference/command-line.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to “Command line”">​</a></h1><p>This document is the reference of the <code>vibator</code> command line: the command that runs the rules, its options, and the subcommands, as they are provided by the base vibator framework.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2><ul><li><a href="#vibator">vibator</a> — Run every enabled rule.</li><li><a href="#reporters">Reporters</a> — The output formats.</li><li><a href="#subcommands">Subcommands</a> — The informational and setup commands.</li><li><a href="#exit-codes">Exit codes</a> — What the process returns.</li></ul><hr><h2 id="vibator" tabindex="-1">vibator <a class="header-anchor" href="#vibator" aria-label="Permalink to “vibator”">​</a></h2><p>The default command runs every enabled rule.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td>--write</td><td>Runs each rule&#39;s <code>fix</code> and rechecks.</td></tr><tr><td>--only &lt;ids&gt;</td><td>Runs only the comma-separated rule ids.</td></tr><tr><td>--config &lt;path&gt;</td><td>Loads configuration from a path.</td></tr><tr><td>--reporter &lt;pretty|json|sarif&gt;</td><td>Chooses the output format. Defaults to <code>pretty</code>.</td></tr><tr><td>--staged</td><td>Scopes the run to files staged for commit.</td></tr><tr><td>--changed</td><td>Scopes the run to uncommitted changes.</td></tr><tr><td>--since &lt;ref&gt;</td><td>Scopes the run to changes since a ref.</td></tr><tr><td>--help</td><td>Prints usage.</td></tr><tr><td>--version</td><td>Prints the version.</td></tr></tbody></table><h2 id="reporters" tabindex="-1">Reporters <a class="header-anchor" href="#reporters" aria-label="Permalink to “Reporters”">​</a></h2><p>The output formats the <code>--reporter</code> flag selects.</p><table tabindex="0"><thead><tr><th>Format</th><th>Description</th></tr></thead><tbody><tr><td>pretty</td><td>A readable, colored report for a terminal. The default.</td></tr><tr><td>json</td><td>The machine-readable format, for a direct integration.</td></tr><tr><td>sarif</td><td>The <a href="https://sarifweb.azurewebsites.net" target="_blank" rel="noreferrer">SARIF</a> interchange format, for tools such as trunk.io and code scanning.</td></tr></tbody></table><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to “Subcommands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td>list</td><td>Prints every rule with its severity and title.</td></tr><tr><td>explain &lt;rule&gt;</td><td>Prints the guideline for a rule.</td></tr><tr><td>init</td><td>Writes a starter <code>.vibator.json</code>.</td></tr><tr><td>skills --install</td><td>Copies the bundled skills into the project.</td></tr></tbody></table><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to “Exit codes”">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td>Findings stay at warning severity or below.</td></tr><tr><td>1</td><td>An error-severity finding, or a rule that crashed.</td></tr></tbody></table>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};